 * @param {number} xp - คะแนนประสบการณ์
 * @returns {{name: string, emoji: string, index: number}}
 */
QV.getRank = function(xp) {
  let currentRank = QV.ranks[0];
  let currentIndex = 0;

  for (let i = 0; i < QV.ranks.length; i++) {
    if (xp >= QV.ranks[i][0]) {
      currentRank = QV.ranks[i];
      currentIndex = i;
    } else {
      break;
    }
  }

  return {
    name: currentRank[1],
    emoji: currentRank[2],
    index: currentIndex
  };
};

